        input_grid.append([5]*8 + [2] + [5]*3)
    elif r == 25:
        input_grid.append([5]*6 + [0, 2] + [5]*4)
    elif r == 26:
        input_grid.append([5]*6 + [2, 0] + [5]*4)
    else:
        input_grid.append([5] * 12)

# Output: start with 0s, copy non-5 values at their positions, propagate up-left diagonal
output_grid = [[0]*cols for _ in range(rows)]
